    "type": "function",
    "function": {
      "name": "exchange_rate",
      "description": "查询汇率（欧洲央行，经由 Frankfurter）。用于货币换算的问题；不要编造汇率。",
      "parameters": {
        "type": "object",
        "properties": {
          "base_currency": {
            "type": "string",
            "description": "源货币的 ISO 代码，例如 CNY、USD、EUR（也接受 RMB）"
