def analyze(datasets):
    out = []
    contract = None
    for ds in datasets:
        if 'annual_sales_target' in ds.get('columns', []):
            contract = ds['rows'][0]
    if contract:
        target = contract['annual_sales_target']['amount']
        cur = contract['annual_sales_target_currency']
        out.append({'title': '年度销售目标', 'detail': '合同「' + contract['title'] + '」年度目标 ' + str(target) + ' ' + cur + '，期限 ' + contract['term_start_date'] + ' 至 ' + contract['term_end_date'] + '。', 'evidence': {'annual_sales_target': target, 'currency': cur}})
    sales = None
    for ds in datasets:
        if 'total_amount' in ds.get('columns', []) and 'month' in ds.get('columns', []):
            sales = ds['rows']
    if sales and contract:
        total = 0.0
        for row in sales:
            try:
                total += float(row['total_amount'])
            except (TypeError, ValueError):
                continue
        target = contract['annual_sales_target']['amount']
        rate = round(total / target * 100, 2)
        out.append({'title': '已确认采购额与完成度', 'detail': '已确认采购额合计 ' + str(round(total, 2)) + ' USD，对照年度目标完成度 ' + str(rate) + '%。', 'evidence': {'confirmed_amount': round(total, 2), 'completion_rate_pct': rate}})
    return out

def analyze(datasets):
    out = []
    trend = None
    for ds in datasets:
        cols = ds.get('columns', [])
        if 'total_amount' in cols and 'total_quantity' in cols:
            trend = ds['rows']
    if trend:
        rows = []
        for r in trend:
            try:
                amt = float(r.get('total_amount'))
            except (TypeError, ValueError):
                continue
            try:
                qty = int(float(r.get('total_quantity')))
            except (TypeError, ValueError):
                qty = 0
            rows.append({'month': r.get('month'), 'total_amount': amt, 'total_quantity': qty})
        rows.sort(key=lambda x: str(x['month']))
        if rows:
            amt_sum = round(sum(x['total_amount'] for x in rows), 2)
            qty_sum = sum(x['total_quantity'] for x in rows)
            out.append({'title': '近月采购规模', 'detail': '2026年5月至8月累计采购金额 ' + str(amt_sum) + ' USD，累计采购箱数 ' + str(qty_sum) + ' 箱。', 'evidence': {'total_amount': amt_sum, 'total_quantity': qty_sum}})
            peak = max(rows, key=lambda x: x['total_amount'])
            out.append({'title': '采购高峰月', 'detail': '采购金额最高月份为 ' + str(peak['month']) + '，金额 ' + str(round(peak['total_amount'], 2)) + ' USD，箱数 ' + str(peak['total_quantity']) + ' 箱。', 'evidence': {'peak_month': str(peak['month']), 'peak_amount': round(peak['total_amount'], 2)}})
            first = rows[0]['total_amount']
            last = rows[-1]['total_amount']
            chg = round((last - first) / first * 100, 2) if first else 0
            out.append({'title': '月度趋势', 'detail': '从 ' + str(rows[0]['month']) + ' 到 ' + str(rows[-1]['month']) + '，采购金额变化 ' + str(chg) + '%。', 'evidence': {'first_amount': round(first, 2), 'last_amount': round(last, 2), 'change_pct': chg}})
    return out

